function visible(actions) {
  const seq = [];
  for (const a of actions) {
    if (a === "turn up") seq.push("U");
    else if (a === "turn down") seq.push("D");
  }
  for (let i = 0; i < seq.length - 1; i++) {
    if (seq[i] === "D" && seq[i + 1] === "U") {
      const precededByUU = i >= 2 && seq[i - 1] === "U" && seq[i - 2] === "U";
      const followedByDD = i + 3 < seq.length && seq[i + 2] === "D" && seq[i + 3] === "D";
      if (!precededByUU && !followedByDD) {
        return { room: "warm" };
      }
    }
  }
  return { room: "cold" };
}

