// Track dial position p (starts 0) and warm flag (starts true): wait does nothing; turn up turns cold if warm and p>=1, turns warm if cold and p<0, then p++; turn down turns cold if warm and p<=0, then p--.
function visible(actions) {
  let p = 0;
  let warm = true;

  for (const action of actions) {
    if (action === "turn up") {
      if (warm && p >= 1) {
        warm = false;
      }
      if (!warm && p < 0) {
        warm = true;
      }
      p += 1;
    } else if (action === "turn down") {
      if (warm && p <= 0) {
        warm = false;
      }
      p -= 1;
    } else if (action === "wait") {
      // do nothing
    }
  }

  return { room: warm ? "warm" : "cold" };
}

